#[test]
fn enrolment_request_challenge_and_proof_round_trip_through_the_v1_wire_contract() {
    let request = EnrollmentRequest {
        request_id: "request-a".into(),
        tenant_id: "tenant-a".into(),
        repository_id: "repository-a".into(),
        proposed_node_id: "node-a".into(),
        display_name: "Build node A".into(),
        public_key_fingerprint: "ed25519:7f3a".into(),
        requested_capabilities: vec!["synchronize.v1".into()],
        created_at: "2026-08-11T00:00:00Z".into(),
        expires_at: "2026-08-11T00:10:00Z".into(),
        // ADR-0085 decision 2: the key itself travels with the fingerprint.
        // Without it the server has only a hash, and decision 5's "Ackplane
        // verifies the signature" is not implementable at all.
        public_key: vec![0x2a; 32],
    };
    let challenge_request = EnrollmentChallengeRequest {
        request_id: request.request_id.clone(),
        tenant_id: request.tenant_id.clone(),
        repository_id: request.repository_id.clone(),
        proposed_node_id: request.proposed_node_id.clone(),
        public_key_fingerprint: request.public_key_fingerprint.clone(),
    };
    let challenge = EnrollmentChallenge {
        request_id: challenge_request.request_id.clone(),
        tenant_id: challenge_request.tenant_id.clone(),
        repository_id: challenge_request.repository_id.clone(),
        proposed_node_id: challenge_request.proposed_node_id.clone(),
        public_key_fingerprint: challenge_request.public_key_fingerprint.clone(),
        nonce: vec![1; 32],
        issued_at: "2026-08-11T00:01:00Z".into(),
        expires_at: "2026-08-11T00:02:00Z".into(),
        state: EnrollmentState::Approved as i32,
    };
    let proof = EnrollmentActivationProof {
        request_id: challenge.request_id.clone(),
        tenant_id: challenge.tenant_id.clone(),
        repository_id: challenge.repository_id.clone(),
        proposed_node_id: challenge.proposed_node_id.clone(),
        public_key_fingerprint: challenge.public_key_fingerprint.clone(),
        nonce: challenge.nonce.clone(),
        signature: vec![2; 64],
    };

    assert_eq!(
        (
            EnrollmentRequest::decode(request.encode_to_vec().as_slice()).unwrap(),
            EnrollmentChallengeRequest::decode(challenge_request.encode_to_vec().as_slice())
                .unwrap(),
            EnrollmentChallenge::decode(challenge.encode_to_vec().as_slice()).unwrap(),
            EnrollmentActivationProof::decode(proof.encode_to_vec().as_slice()).unwrap(),
        ),
        (request, challenge_request, challenge, proof)
    );
}

// The key travels once, at enrolment. Activation carries the fingerprint, the
// nonce and the signature, and deliberately no key: approval binds to the
// fingerprint (ADR-0085 decision 4), so a proof that could carry its own key
// would let a node present a different one after approval and be verified
// against it. This asserts that absence, because it is a security property
// rather than an oversight, and a later "helpful" addition would remove it.
#[test]
fn only_enrolment_carries_the_public_key_so_approval_cannot_be_sidestepped() {
    let descriptor = EnrollmentActivationProof::default();
    let encoded = descriptor.encode_to_vec();
    assert!(encoded.is_empty(), "a default proof encodes to nothing");

    // Field 10 is the enrolment request's public key. Nothing decodes it here,
    // so a proof carrying one would be an unknown field rather than a key the
    // server could be persuaded to trust.
    let request = EnrollmentRequest {
        public_key: vec![0x2a; 32],
        ..EnrollmentRequest::default()
    };
    assert_eq!(
        EnrollmentRequest::decode(request.encode_to_vec().as_slice())
            .unwrap()
            .public_key,
        vec![0x2a; 32],
        "enrolment carries the key"
    );
}

#[test]
fn node_key_rotation_request_and_result_round_trip_through_the_v1_wire_contract() {
    let request = KeyRotationRequest {
        tenant_id: "tenant-a".into(),
        repository_id: "repository-a".into(),
        node_id: "node-a".into(),
        current_key_id: "key-current".into(),
        successor_key_id: "key-successor".into(),
        successor_public_key_fingerprint: "ed25519:7f3a".into(),
        successor_public_key: vec![3; 32],
        current_key_signature: vec![1; 64],
        successor_key_signature: vec![2; 64],
        requested_overlap_seconds: 3_600,
    };
    let result = KeyRotationResult {
        node_id: request.node_id.clone(),
        current_key_id: request.current_key_id.clone(),
        successor_key_id: request.successor_key_id.clone(),
        outcome: KeyRotationOutcome::Applied as i32,
        rejection_reason: KeyRotationRejectionReason::Unspecified as i32,
        diagnostic: "rotation accepted".into(),
    };

    assert_eq!(
        (
            KeyRotationRequest::decode(request.encode_to_vec().as_slice()).unwrap(),
            KeyRotationResult::decode(result.encode_to_vec().as_slice()).unwrap(),
        ),
        (request, result)
    );
}
